/*!
 * Lessons Learned Builder for ProjectManagers.net
 * Place in: /wp-content/uploads/js/lessons-learned-builder.js
 * Needs a container: <div id="pmll-app"></div>
 */
(function(){'use strict';var root=document.getElementById('pmll-app');if(!root)return;var KEY='pmll-lessons-learned-v1';var PHASES=['Initiation','Planning','Execution','Monitoring & Control','Closure'];var CATEGORIES=['Scope','Schedule','Cost','Quality','Resources','Communication','Risk','Stakeholders','Procurement','Technical','Process','Other'];var IMPACTS=['High','Medium','Low'];var STATUSES=['Open','In progress','Done','No action needed'];var TYPES={well:'Went well',improve:'Needs improvement'};var PROMPTS=[{label:'Planning accuracy',type:'improve',phase:'Planning',category:'Schedule',q:'Were the estimates and the schedule realistic? Where were they furthest off, and why?'},{label:'Communication',type:'improve',phase:'Execution',category:'Communication',q:'Did information reach the right people at the right time? Give one concrete example.'},{label:'Resource availability',type:'improve',phase:'Execution',category:'Resources',q:'Were people, tools and budget available when the work needed them?'},{label:'Improvising',type:'improve',phase:'Execution',category:'Process',q:'Where did the team have to improvise or adapt? What was missing from the plan?'},{label:'Change requests',type:'improve',phase:'Monitoring & Control',category:'Scope',q:'Looking at the change log, which change requests helped or hurt the project?'},{label:'Success to repeat',type:'well',phase:'Execution',category:'Process',q:'What worked so well that it should become standard practice on the next project?'}];var VAGUE=['could have been better','could be better','should have been better','took too long','went well','was good','was bad','was fine','poor communication','better communication','more communication','lack of communication','not enough time','issues with','problems with','more planning','better planning'];var state=load()||blankState();var filters={q:'',type:'',phase:'',category:'',status:'',sort:'id'};var openIds={};var tab=state.lessons.length?'log':'project';var saveTimer=null;function blankState(){return{project:{name:'',type:'',manager:'',sponsor:'',department:'',start:'',end:'',reportDate:today(),preparedBy:'',summary:''},lessons:[],nextId:1}}
function pad(n){return(n<10?'0':'')+n}
function isoDate(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function today(){return isoDate(new Date())}
function addDays(n){var d=new Date();d.setDate(d.getDate()+n);return isoDate(d)}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function nl(s){return esc(s).replace(/\n/g,'<br>')}
function trim(s){return String(s||'').trim()}
function wc(s){return trim(s)?trim(s).split(/\s+/).length:0}
function lid(id){return'LL-'+pad(id)}
function find(id){id=Number(id);for(var i=0;i<state.lessons.length;i++)if(state.lessons[i].id===id)return state.lessons[i];return null}
function joinList(a){return a.length<2?a.join(''):a.slice(0,-1).join(', ')+' and '+a[a.length-1]}
function fmtDate(s){if(!s)return'';var p=s.split('-');if(p.length!==3)return s;var m=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(p[1])-1];return m+' '+Number(p[2])+', '+p[0]}
function options(list,sel,blankLabel){var h=blankLabel!=null?'<option value="">'+esc(blankLabel)+'</option>':'';list.forEach(function(v){var val=typeof v==='object'?v.v:v,lab=typeof v==='object'?v.l:v;h+='<option value="'+esc(val)+'"'+(val===sel?' selected':'')+'>'+esc(lab)+'</option>'});return h}
var TYPE_OPTS=[{v:'well',l:'Went well'},{v:'improve',l:'Needs improvement'}];function load(){try{var raw=window.localStorage.getItem(KEY);if(!raw)return null;var s=JSON.parse(raw);if(!s||!Array.isArray(s.lessons)||!s.project)return null;return s}catch(e){return null}}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(function(){try{window.localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}},250)}
function newLesson(o){o=o||{};var l={id:state.nextId++,title:o.title||'',type:o.type||'improve',phase:o.phase||'Execution',category:o.category||'Process',impact:o.impact||'Medium',what:o.what||'',why:o.why||'',rec:o.rec||'',action:o.action||'',owner:o.owner||'',due:o.due||'',status:o.status||'Open',raisedBy:o.raisedBy||'',prompt:o.prompt||''};state.lessons.push(l);return l}
function isVague(s){var t=trim(s).toLowerCase();for(var i=0;i<VAGUE.length;i++)if(t.indexOf(VAGUE[i])!==-1)return!0;return!1}
function isOverdue(l){return!!l.due&&l.status!=='Done'&&l.status!=='No action needed'&&l.due<today()}
function issues(l){var out=[];var w=wc(l.what);if(!w)out.push('Describe what happened.');else if(w<10||(w<20&&isVague(l.what)))out.push('Too vague to reuse. Add specifics: when, where, how much, and who was affected.');if(!wc(l.why))out.push('Add the root cause: why did it happen?');if(!wc(l.rec))out.push(l.type==='well'?'Say how a future team can repeat this success.':'Add a recommendation: what should a future team do differently?');if(l.type==='improve'&&l.impact!=='Low'&&l.status!=='No action needed'){var miss=[];if(!trim(l.action))miss.push('an action');if(!trim(l.owner))miss.push('an owner');if(!l.due)miss.push('a due date');if(miss.length)out.push('Assign '+joinList(miss)+' so this lesson leads to a change.');}
return out}
function reportChecks(){var L=state.lessons,out=[];if(!L.length)return[{lvl:'info',t:'Add your first lesson. Start with one thing that went well and one thing to improve.'}];var well=L.filter(function(l){return l.type==='well'}).length;var imp=L.length-well;if(L.length>=3&&!well)out.push({lvl:'warn',t:'Every lesson is a problem. Record what went well too, so good practices get repeated on purpose.'});if(L.length>=3&&!imp)out.push({lvl:'info',t:'No improvement areas yet. Even successful projects have something to do better next time.'});var weak=L.filter(function(l){return issues(l).length}).length;if(weak)out.push({lvl:'warn',t:weak+(weak===1?' lesson needs':' lessons need')+' more detail before a future team can act on '+(weak===1?'it.':'them.')});var od=L.filter(isOverdue).length;if(od)out.push({lvl:'warn',t:od+(od===1?' action is':' actions are')+' past due.'});var empty=PHASES.filter(function(p){return!L.some(function(l){return l.phase===p})});if(L.length>=5&&empty.length)out.push({lvl:'info',t:'No lessons yet for '+joinList(empty)+'. Add notes at the end of each phase while details are fresh.'});if(!trim(state.project.name))out.push({lvl:'info',t:'Add a project name so this report is easy to find at the next kickoff.'});if(!out.length)out.push({lvl:'ok',t:'This report is specific, balanced and has owners for its actions.'});return out}
function readyCount(){return state.lessons.filter(function(l){return!issues(l).length}).length}
function fileBase(){var n=trim(state.project.name).replace(/[^\w\s-]/g,'').replace(/\s+/g,'-')||'Project';return n+'_Lessons-Learned_'+(state.project.reportDate||today())}
function renderShell(){root.innerHTML='<div class="pmll-toolbar" role="toolbar" aria-label="Lessons learned actions">'+'<button type="button" class="pmll-btn pmll-primary" data-act="add">+ Add lesson</button>'+'<span class="pmll-sep" aria-hidden="true"></span>'+'<button type="button" class="pmll-btn" data-act="word">Download Word</button>'+'<button type="button" class="pmll-btn" data-act="csv">Download CSV</button>'+'<button type="button" class="pmll-btn" data-act="print">Print</button>'+'<span class="pmll-sep" aria-hidden="true"></span>'+'<button type="button" class="pmll-btn pmll-quiet" data-act="example">Load example</button>'+'<button type="button" class="pmll-btn pmll-quiet" data-act="blank">Start blank</button>'+'</div>'+'<div class="pmll-tabs" role="tablist">'+tabBtn('project','Project details')+tabBtn('log','Lessons log')+tabBtn('summary','Summary and actions')+'</div>'+'<div class="pmll-panel" id="pmll-p-project" role="tabpanel"></div>'+'<div class="pmll-panel" id="pmll-p-log" role="tabpanel"></div>'+'<div class="pmll-panel" id="pmll-p-summary" role="tabpanel"></div>'+'<div class="pmll-legend">'+'<p><span class="pmll-dot pmll-dot-well"></span><strong>Went well</strong> A practice worth repeating. Say why it worked.</p>'+'<p><span class="pmll-dot pmll-dot-improve"></span><strong>Needs improvement</strong> A problem to avoid. Give it an action, an owner and a date.</p>'+'<p class="pmll-tip">Every lesson answers three questions: what happened, why it happened, and what the next team should do. Your log is saved in this browser so you can come back to it.</p>'+'</div>';renderProject();renderLog();showTab(tab)}
function tabBtn(id,label){return'<button type="button" role="tab" class="pmll-tab" data-act="tab" data-tab="'+id+'" id="pmll-t-'+id+'">'+label+(id==='log'?' <span class="pmll-count" data-count="lessons"></span>':'')+'</button>'}
function showTab(t){tab=t;['project','log','summary'].forEach(function(id){var b=root.querySelector('#pmll-t-'+id),p=root.querySelector('#pmll-p-'+id);var on=id===t;b.setAttribute('aria-selected',on?'true':'false');b.classList.toggle('is-active',on);p.hidden=!on});if(t==='summary')renderSummary();updateCounts()}
function updateCounts(){var c=root.querySelector('[data-count="lessons"]');if(c)c.textContent=state.lessons.length}
function field(label,inner,cls){return'<label class="pmll-field'+(cls?' '+cls:'')+'"><span class="pmll-label">'+label+'</span>'+inner+'</label>'}
function renderProject(){var p=state.project;function inp(k,type,ph){return'<input type="'+(type||'text')+'" data-p="'+k+'" value="'+esc(p[k])+'"'+(ph?' placeholder="'+esc(ph)+'"':'')+'>'}
root.querySelector('#pmll-p-project').innerHTML='<div class="pmll-grid">'+field('Project name',inp('name','text','e.g. Customer Portal Relaunch'),'pmll-span2')+field('Project type',inp('type','text','e.g. Software, Construction, Event'))+field('Department or client',inp('department'))+field('Project manager',inp('manager'))+field('Sponsor',inp('sponsor'))+field('Start date',inp('start','date'))+field('End date',inp('end','date'))+field('Report date',inp('reportDate','date'))+field('Prepared by',inp('preparedBy'))+field('Executive summary','<textarea rows="4" data-p="summary" placeholder="Two or three sentences on the project outcome and the most important lessons for the next team.">'+esc(p.summary)+'</textarea>','pmll-span-all')+'</div>'+'<p class="pmll-filename">Suggested file name for your archive: <code data-filename>'+esc(fileBase())+'</code></p>'+'<div class="pmll-next"><button type="button" class="pmll-btn pmll-primary" data-act="tab" data-tab="log">Continue to the lessons log</button></div>'}
function renderLog(){var f=filters;root.querySelector('#pmll-p-log').innerHTML='<div class="pmll-prompts"><span>Need a starting point? Add a lesson from a team survey question:</span>'+PROMPTS.map(function(pr,i){return'<button type="button" class="pmll-chip" data-act="prompt" data-i="'+i+'">'+esc(pr.label)+'</button>'}).join('')+'</div>'+'<div class="pmll-filters">'+'<input type="search" data-filter="q" placeholder="Search lessons" value="'+esc(f.q)+'" aria-label="Search lessons">'+'<select data-filter="type" aria-label="Filter by type">'+options(TYPE_OPTS,f.type,'All types')+'</select>'+'<select data-filter="phase" aria-label="Filter by phase">'+options(PHASES,f.phase,'All phases')+'</select>'+'<select data-filter="category" aria-label="Filter by category">'+options(CATEGORIES,f.category,'All categories')+'</select>'+'<select data-filter="status" aria-label="Filter by status">'+options(STATUSES,f.status,'Any status')+'</select>'+'<select data-filter="sort" aria-label="Sort">'+options([{v:'id',l:'Sort by number'},{v:'phase',l:'Sort by phase'},{v:'impact',l:'Sort by impact'},{v:'checks',l:'Needs work first'}],f.sort)+'</select>'+'</div>'+'<div class="pmll-listbar"><span data-showing></span><span><button type="button" class="pmll-link" data-act="expand">Expand all</button> <button type="button" class="pmll-link" data-act="collapse">Collapse all</button></span></div>'+'<div class="pmll-list" data-list></div>';renderList()}
function visibleLessons(){var f=filters,q=trim(f.q).toLowerCase();var list=state.lessons.filter(function(l){if(f.type&&l.type!==f.type)return!1;if(f.phase&&l.phase!==f.phase)return!1;if(f.category&&l.category!==f.category)return!1;if(f.status&&l.status!==f.status)return!1;if(q){var hay=[lid(l.id),l.title,l.what,l.why,l.rec,l.action,l.owner,l.raisedBy,l.category,l.phase].join(' ').toLowerCase();if(hay.indexOf(q)===-1)return!1}
return!0});var s=f.sort;list.sort(function(a,b){if(s==='phase')return(PHASES.indexOf(a.phase)-PHASES.indexOf(b.phase))||a.id-b.id;if(s==='impact')return(IMPACTS.indexOf(a.impact)-IMPACTS.indexOf(b.impact))||a.id-b.id;if(s==='checks')return(issues(b).length-issues(a).length)||a.id-b.id;return a.id-b.id});return list}
function renderList(){var box=root.querySelector('[data-list]');if(!box)return;var list=visibleLessons();var showing=root.querySelector('[data-showing]');if(!state.lessons.length){box.innerHTML='<div class="pmll-empty"><p><strong>No lessons yet.</strong> Add one now, pick a survey question above, or load the example to see a finished log.</p>'+'<button type="button" class="pmll-btn pmll-primary" data-act="add">+ Add lesson</button> <button type="button" class="pmll-btn" data-act="example">Load example</button></div>';showing.textContent='';return}
showing.textContent=list.length===state.lessons.length?state.lessons.length+(state.lessons.length===1?' lesson':' lessons'):'Showing '+list.length+' of '+state.lessons.length+' lessons';if(!list.length){box.innerHTML='<div class="pmll-empty"><p>No lessons match these filters.</p><button type="button" class="pmll-btn" data-act="clearfilters">Clear filters</button></div>';return}
box.innerHTML=list.map(cardHTML).join('')}
function headHTML(l){var iss=issues(l);return'<span class="pmll-id">'+lid(l.id)+'</span>'+'<span class="pmll-type">'+TYPES[l.type]+'</span>'+'<span class="pmll-card-title">'+(trim(l.title)?esc(l.title):'<em>Untitled lesson</em>')+'</span>'+'<span class="pmll-tags">'+'<span class="pmll-tag">'+esc(l.phase)+'</span>'+'<span class="pmll-tag">'+esc(l.category)+'</span>'+'<span class="pmll-tag pmll-imp-'+l.impact.toLowerCase()+'">'+esc(l.impact)+' impact</span>'+(l.type==='improve'||trim(l.action)?'<span class="pmll-tag'+(isOverdue(l)?' pmll-overdue':'')+'">'+(isOverdue(l)?'Overdue':esc(l.status))+'</span>':'')+'</span>'+'<span class="pmll-check '+(iss.length?'is-warn':'is-ok')+'">'+(iss.length?iss.length+(iss.length===1?' fix':' fixes'):'&#10003; Ready to reuse')+'</span>'+'<span class="pmll-chev" aria-hidden="true"></span>'}
function issuesHTML(l){var iss=issues(l);if(!iss.length)return'<p class="pmll-ok-line">&#10003; Specific, explained and actionable. A future team can use this lesson.</p>';return'<ul>'+iss.map(function(t){return'<li>'+esc(t)+'</li>'}).join('')+'</ul>'}
function cardHTML(l){var open=!!openIds[l.id];var isWell=l.type==='well';function ta(k,label,ph,rows){return field(label,'<textarea rows="'+(rows||3)+'" data-f="'+k+'" placeholder="'+esc(ph)+'">'+esc(l[k])+'</textarea>','pmll-span-all')}
return'<article class="pmll-card pmll-'+l.type+(open?' is-open':'')+'" data-lid="'+l.id+'">'+'<button type="button" class="pmll-card-head" data-act="toggle" aria-expanded="'+open+'">'+headHTML(l)+'</button>'+'<div class="pmll-card-body"'+(open?'':' hidden')+'>'+(l.prompt?'<p class="pmll-prompt">'+esc(l.prompt)+'</p>':'')+'<div class="pmll-grid">'+field('Lesson title','<input type="text" data-f="title" value="'+esc(l.title)+'" placeholder="A short headline a future PM could search for">','pmll-span2')+field('Type','<select data-f="type">'+options(TYPE_OPTS,l.type)+'</select>')+field('Raised by','<input type="text" data-f="raisedBy" value="'+esc(l.raisedBy)+'" placeholder="Name or role">')+field('Phase','<select data-f="phase">'+options(PHASES,l.phase)+'</select>')+field('Category','<select data-f="category">'+options(CATEGORIES,l.category)+'</select>')+field('Impact on the project','<select data-f="impact">'+options(IMPACTS,l.impact)+'</select>')+'<span class="pmll-spacer"></span>'+ta('what','What happened?','Be specific: when, where, how much, who was affected. "Communication could have been better" is too vague to reuse.',3)+ta('why','Why did it happen? (root cause)','The underlying cause, not the symptom.',2)+ta('rec',isWell?'How can a future team repeat this?':'What should a future team do differently?',isWell?'The practice to keep, and when to apply it.':'A concrete recommendation someone new to the project could follow.',2)+'<div class="pmll-action-row pmll-span-all">'+field('Follow-up action','<input type="text" data-f="action" value="'+esc(l.action)+'" placeholder="e.g. Update the estimating checklist">','pmll-grow')+field('Owner','<input type="text" data-f="owner" value="'+esc(l.owner)+'">')+field('Due date','<input type="date" data-f="due" value="'+esc(l.due)+'">')+field('Status','<select data-f="status">'+options(STATUSES,l.status)+'</select>')+'</div>'+'</div>'+'<div class="pmll-issues" data-issues>'+issuesHTML(l)+'</div>'+'<div class="pmll-card-actions">'+'<button type="button" class="pmll-link" data-act="collapse-one">Done editing</button>'+'<span><button type="button" class="pmll-link" data-act="dup">Duplicate</button> <button type="button" class="pmll-link pmll-danger" data-act="del">Delete</button></span>'+'</div>'+'</div>'+'</article>'}
function refreshCard(card,l){card.className='pmll-card pmll-'+l.type+(openIds[l.id]?' is-open':'');card.querySelector('.pmll-card-head').innerHTML=headHTML(l);card.querySelector('[data-issues]').innerHTML=issuesHTML(l)}
function bars(key,list){var rows=list.map(function(k){var w=0,im=0;state.lessons.forEach(function(l){if(l[key]===k){if(l.type==='well')w++;else im++}});return{k:k,w:w,im:im}}).filter(function(r){return key==='phase'||r.w+r.im});var max=Math.max.apply(null,rows.map(function(r){return r.w+r.im}).concat([1]));return rows.map(function(r){return'<div class="pmll-bar-row"><span class="pmll-bar-label">'+esc(r.k)+'</span>'+'<span class="pmll-bar-track">'+(r.w?'<span class="pmll-bar pmll-bar-well" style="width:'+(r.w/max*100)+'%" title="'+r.w+' went well"></span>':'')+(r.im?'<span class="pmll-bar pmll-bar-improve" style="width:'+(r.im/max*100)+'%" title="'+r.im+' to improve"></span>':'')+'</span><span class="pmll-bar-num">'+(r.w+r.im)+'</span></div>'}).join('')}
function actionLessons(){return state.lessons.filter(function(l){return trim(l.action)||(l.type==='improve'&&l.status!=='No action needed')}).sort(function(a,b){return(a.due||'9999').localeCompare(b.due||'9999')||a.id-b.id})}
function renderSummary(){var L=state.lessons;var well=L.filter(function(l){return l.type==='well'}).length;var openA=actionLessons().filter(function(l){return l.status!=='Done'}).length;var ready=readyCount();var pct=L.length?Math.round(ready/L.length*100):0;var acts=actionLessons();root.querySelector('#pmll-p-summary').innerHTML='<div class="pmll-score">'+'<div class="pmll-ring" style="--pmll-pct:'+pct+'"><span>'+(L.length?pct+'%':'&ndash;')+'</span></div>'+'<div><p class="pmll-score-title">'+ready+' of '+L.length+' lessons are ready to reuse</p>'+'<p class="pmll-score-sub">'+well+' went well, '+(L.length-well)+' to improve, '+openA+' open '+(openA===1?'action':'actions')+'</p></div>'+'</div>'+'<ul class="pmll-checks">'+reportChecks().map(function(c){return'<li class="pmll-c-'+c.lvl+'">'+esc(c.t)+'</li>'}).join('')+'</ul>'+(L.length?'<div class="pmll-cols">'+'<section><h4>Lessons by phase</h4>'+bars('phase',PHASES)+'</section>'+'<section><h4>Lessons by category</h4>'+bars('category',CATEGORIES)+'</section>'+'</div>'+'<p class="pmll-key"><span class="pmll-dot pmll-dot-well"></span>Went well <span class="pmll-dot pmll-dot-improve"></span>Needs improvement</p>'+'<h4>Action plan</h4>'+(acts.length?'<div class="pmll-table-wrap"><table class="pmll-table"><thead><tr><th>Lesson</th><th>Action</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead><tbody>'+acts.map(function(l){var od=isOverdue(l);return'<tr'+(od?' class="is-overdue"':'')+'><td><button type="button" class="pmll-link" data-act="goto" data-id="'+l.id+'">'+lid(l.id)+'</button> '+esc(l.title)+'</td>'+'<td>'+(trim(l.action)?esc(l.action):'<span class="pmll-missing">No action yet</span>')+'</td>'+'<td>'+(trim(l.owner)?esc(l.owner):'<span class="pmll-missing">Unassigned</span>')+'</td>'+'<td>'+(l.due?esc(fmtDate(l.due)):'<span class="pmll-missing">No date</span>')+'</td>'+'<td>'+(od?'<strong class="pmll-od">Overdue</strong>':esc(l.status))+'</td></tr>'}).join('')+'</tbody></table></div>':'<p class="pmll-muted">No follow-up actions yet.</p>')+'<div class="pmll-store"><h4>Store it so the next team finds it</h4>'+'<p>Save the Word file as <code>'+esc(fileBase())+'.doc</code> in your shared lessons learned folder, and add a review of past reports to your next project kickoff.</p></div>':'')}
function reportHTML(forWord){var p=state.project,L=state.lessons.slice().sort(function(a,b){return a.id-b.id});var well=L.filter(function(l){return l.type==='well'}),imp=L.filter(function(l){return l.type==='improve'});var css='body{font-family:Calibri,Arial,sans-serif;color:#1c2b3a;font-size:11pt;line-height:1.4;margin:24px}'+'h1{font-size:22pt;color:#12325b;margin:0 0 2px}h2{font-size:15pt;color:#12325b;border-bottom:2px solid #ee7a1f;padding-bottom:3px;margin:22px 0 10px}'+'.sub{font-size:13pt;color:#4a5b6e;margin:0 0 14px}table{border-collapse:collapse;width:100%;margin:0 0 12px}'+'th,td{border:1px solid #c9d3df;padding:5px 7px;text-align:left;vertical-align:top;font-size:10pt}th{background:#eef2f7;width:26%}'+'.lh td{background:#12325b;color:#fff;font-weight:bold}.lh.well td{background:#2f7d4f}.lh.improve td{background:#b85a12}'+'.at th{width:auto;background:#12325b;color:#fff}.muted{color:#6b7a8a}'+'@media print{body{margin:0}.lesson{page-break-inside:avoid}}';function info(k,v){return v?'<tr><th>'+k+'</th><td>'+nl(v)+'</td></tr>':''}
function lessonTable(l){return'<table class="lesson"><tr class="lh '+l.type+'"><td colspan="2">'+lid(l.id)+': '+(esc(l.title)||'Untitled lesson')+'</td></tr>'+'<tr><th>Phase / Category / Impact</th><td>'+esc(l.phase)+' / '+esc(l.category)+' / '+esc(l.impact)+'</td></tr>'+info('What happened',l.what)+info('Why it happened',l.why)+info(l.type==='well'?'How to repeat it':'What to do differently',l.rec)+(trim(l.action)?'<tr><th>Follow-up action</th><td>'+esc(l.action)+(l.owner?'<br><span class="muted">Owner: '+esc(l.owner)+'</span>':'')+(l.due?'<br><span class="muted">Due: '+esc(fmtDate(l.due))+' ('+esc(l.status)+')</span>':'')+'</td></tr>':'')+info('Raised by',l.raisedBy)+'</table>'}
var acts=actionLessons();var body='<h1>Lessons Learned Report</h1><p class="sub">'+(esc(p.name)||'Untitled project')+'</p>'+'<table>'+info('Project type',p.type)+info('Department or client',p.department)+info('Project manager',p.manager)+info('Sponsor',p.sponsor)+info('Project dates',[fmtDate(p.start),fmtDate(p.end)].filter(Boolean).join(' to '))+info('Report date',fmtDate(p.reportDate))+info('Prepared by',p.preparedBy)+'<tr><th>Lessons recorded</th><td>'+L.length+' ('+well.length+' went well, '+imp.length+' to improve)</td></tr></table>'+(trim(p.summary)?'<h2>Executive summary</h2><p>'+nl(p.summary)+'</p>':'')+'<h2>What went well</h2>'+(well.length?well.map(lessonTable).join(''):'<p class="muted">None recorded.</p>')+'<h2>What needs improvement</h2>'+(imp.length?imp.map(lessonTable).join(''):'<p class="muted">None recorded.</p>')+'<h2>Action plan</h2>'+(acts.length?'<table class="at"><tr><th>Lesson</th><th>Action</th><th>Owner</th><th>Due</th><th>Status</th></tr>'+acts.map(function(l){return'<tr><td>'+lid(l.id)+'</td><td>'+esc(l.action)+'</td><td>'+esc(l.owner)+'</td><td>'+esc(fmtDate(l.due))+'</td><td>'+(isOverdue(l)?'Overdue':esc(l.status))+'</td></tr>'}).join('')+'</table>':'<p class="muted">No follow-up actions.</p>')+'<p class="muted" style="margin-top:24px;font-size:9pt">Created with the free Lessons Learned Builder at ProjectManagers.net</p>';var head=forWord?'<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><title>Lessons Learned Report</title><!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom></w:WordDocument></xml><![endif]-->':'<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+esc(fileBase())+'</title>';return head+'<style>'+css+'</style></head><body>'+body+'</body></html>'}
function download(name,content,mime){var blob=new Blob([content],{type:mime});var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove()},500)}
function csv(){var cols=[['ID',function(l){return lid(l.id)}],['Title','title'],['Type',function(l){return TYPES[l.type]}],['Phase','phase'],['Category','category'],['Impact','impact'],['What happened','what'],['Why it happened','why'],['Recommendation','rec'],['Follow-up action','action'],['Owner','owner'],['Due date','due'],['Status',function(l){return isOverdue(l)?'Overdue':l.status}],['Raised by','raisedBy'],['Ready to reuse',function(l){return issues(l).length?'No':'Yes'}]];function cell(v){v=String(v==null?'':v);return/[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
var rows=[cols.map(function(c){return c[0]}).join(',')];state.lessons.slice().sort(function(a,b){return a.id-b.id}).forEach(function(l){rows.push(cols.map(function(c){return cell(typeof c[1]==='function'?c[1](l):l[c[1]])}).join(','))});download(fileBase()+'.csv','\ufeff'+rows.join('\r\n'),'text/csv;charset=utf-8')}
function printReport(){var w=window.open('','_blank');if(!w){window.alert('Your browser blocked the print window. Allow pop-ups for this site, or use Download Word and print from Word.');return}
w.document.open();w.document.write(reportHTML(!1));w.document.close();w.focus();setTimeout(function(){w.print()},300)}
function loadExample(){state=blankState();state.project={name:'Customer Portal Relaunch',type:'Software',manager:'Dana Whitfield',sponsor:'VP Customer Experience',department:'Digital Services',start:addDays(-190),end:addDays(-10),reportDate:today(),preparedBy:'Dana Whitfield',summary:'The new portal launched two weeks late and 4% over budget, with customer satisfaction up 18 points in the first month. The biggest lessons concern data migration estimates and change control. Early sponsor workshops and test automation are worth repeating on every web project.'};newLesson({title:'Early scope workshops cut design review cycles',type:'well',phase:'Initiation',category:'Stakeholders',impact:'High',what:'We ran two half-day workshops in week 2 with the sponsor and three department leads to agree on scope and acceptance criteria. Design reviews later needed one round instead of the usual three.',why:'All decision makers heard each other\'s priorities in the same room, so conflicting requirements came out before design started.',rec:'Book scope workshops with every approver in the first two weeks of any project that spans more than two departments.',action:'Add scope workshops to the PMO kickoff checklist',owner:'PMO lead',due:addDays(-20),status:'Done',raisedBy:'Dana Whitfield'});newLesson({title:'Data migration estimate was 60% too low',type:'improve',phase:'Planning',category:'Schedule',impact:'High',what:'Migrating 48,000 customer records was estimated at 10 days and took 16. Test loads exposed duplicate accounts and inconsistent address formats that nobody had profiled.',why:'The estimate was based on record counts only. No one profiled the source data before the schedule was baselined.',rec:'Profile the source data and run a sample load before committing to any migration estimate.',action:'Add a data profiling task to the migration plan template',owner:'Data lead',due:addDays(21),status:'In progress',raisedBy:'Integration team'});newLesson({title:'Status updates',type:'improve',phase:'Execution',category:'Communication',impact:'Medium',what:'Communication could have been better.',raisedBy:'Survey response'});newLesson({title:'Automated regression tests caught 31 defects before UAT',type:'well',phase:'Execution',category:'Quality',impact:'Medium',what:'The automated regression suite built in sprint 1 caught 31 defects before user acceptance testing. UAT finished in 4 days instead of the planned 8.',why:'Test automation was funded in the original plan and built from the start, instead of being squeezed in at the end.',rec:'Budget automated regression testing from the first sprint of every software project.',raisedBy:'QA lead'});newLesson({title:'Change requests approved without impact analysis',type:'improve',phase:'Monitoring & Control',category:'Scope',impact:'High',what:'Four change requests were approved by email in month 3. Together they added 12 days of work, but the schedule and budget were not updated until the steering committee asked why milestone 4 slipped.',why:'Any director could approve a change, and the change log was not reviewed at weekly status meetings.',rec:'Send every change request through one change log with schedule and cost impact filled in before approval.',action:'Update the change control procedure and review the change log weekly',owner:'Project manager',due:addDays(-5),status:'Open',raisedBy:'Dana Whitfield'});newLesson({title:'Senior developer shared with another project',type:'improve',phase:'Execution',category:'Resources',impact:'Medium',what:'From week 6 our senior integration developer was assigned 50% to the billing upgrade. API work slipped two weeks and the team found out at a stand-up.',why:'The allocation was agreed verbally between managers and never recorded in the resource plan.',rec:'Confirm shared resources in writing with both sponsors before baselining the schedule.',raisedBy:'Dev team'});newLesson({title:'Lessons captured at every phase gate',type:'well',phase:'Closure',category:'Process',impact:'Low',what:'The team spent 20 minutes at each phase gate adding to this log, so the final report took one afternoon instead of a week of interviews.',why:'It was a standing agenda item owned by the project manager, not an end-of-project task.',rec:'Make lessons learned a standing item at every phase gate review.',raisedBy:'Dana Whitfield'});openIds={3:!0};filters={q:'',type:'',phase:'',category:'',status:'',sort:'id'};save();tab='log';renderShell()}
root.addEventListener('input',function(e){var t=e.target;if(t.dataset.p){state.project[t.dataset.p]=t.value;save();var fn=root.querySelector('[data-filename]');if(fn)fn.textContent=fileBase();return}
if(t.dataset.f){var card=t.closest('[data-lid]'),l=card&&find(card.dataset.lid);if(!l)return;l[t.dataset.f]=t.value;save();if(t.dataset.f==='type'){var recLabel=card.querySelector('[data-f="rec"]').closest('.pmll-field').querySelector('.pmll-label');recLabel.textContent=l.type==='well'?'How can a future team repeat this?':'What should a future team do differently?'}
refreshCard(card,l);return}
if(t.dataset.filter){filters[t.dataset.filter]=t.value;renderList()}});root.addEventListener('click',function(e){var b=e.target.closest('[data-act]');if(!b||!root.contains(b))return;var act=b.dataset.act,card=b.closest('[data-lid]'),l=card?find(card.dataset.lid):null;switch(act){case 'tab':showTab(b.dataset.tab);if(b.dataset.tab==='log')renderList();break;case 'add':addAndOpen({});break;case 'prompt':var pr=PROMPTS[Number(b.dataset.i)];addAndOpen({title:pr.label,type:pr.type,phase:pr.phase,category:pr.category,prompt:pr.q});break;case 'toggle':openIds[l.id]=!openIds[l.id];card.querySelector('.pmll-card-body').hidden=!openIds[l.id];b.setAttribute('aria-expanded',!!openIds[l.id]);card.classList.toggle('is-open',!!openIds[l.id]);break;case 'collapse-one':openIds[l.id]=!1;refreshCard(card,l);card.querySelector('.pmll-card-body').hidden=!0;card.querySelector('.pmll-card-head').setAttribute('aria-expanded','false');card.querySelector('.pmll-card-head').focus();break;case 'expand':state.lessons.forEach(function(x){openIds[x.id]=!0});renderList();break;case 'collapse':openIds={};renderList();break;case 'dup':var c=JSON.parse(JSON.stringify(l));delete c.id;c.title=(c.title?c.title+' (copy)':'');addAndOpen(c);break;case 'del':if(window.confirm('Delete '+lid(l.id)+(l.title?' "'+l.title+'"':'')+'? This cannot be undone.')){state.lessons=state.lessons.filter(function(x){return x.id!==l.id});delete openIds[l.id];save();renderList();updateCounts()}
break;case 'goto':filters={q:'',type:'',phase:'',category:'',status:'',sort:filters.sort};openIds[Number(b.dataset.id)]=!0;showTab('log');renderLog();var target=root.querySelector('[data-lid="'+b.dataset.id+'"]');if(target){target.scrollIntoView({behavior:'smooth',block:'start'});target.querySelector('.pmll-card-head').focus({preventScroll:!0})}
break;case 'clearfilters':filters={q:'',type:'',phase:'',category:'',status:'',sort:'id'};renderLog();break;case 'word':download(fileBase()+'.doc','\ufeff'+reportHTML(!0),'application/msword');break;case 'csv':csv();break;case 'print':printReport();break;case 'example':if(!state.lessons.length||window.confirm('Replace your current log with the example project?'))loadExample();break;case 'blank':if(!state.lessons.length&&!trim(state.project.name)){showTab('project');break}
if(window.confirm('Clear the project details and all lessons? This cannot be undone.')){state=blankState();openIds={};filters={q:'',type:'',phase:'',category:'',status:'',sort:'id'};save();tab='project';renderShell()}
break}});function addAndOpen(o){var l=newLesson(o);openIds[l.id]=!0;filters={q:'',type:'',phase:'',category:'',status:'',sort:'id'};save();showTab('log');renderLog();updateCounts();var card=root.querySelector('[data-lid="'+l.id+'"]');if(card){card.scrollIntoView({behavior:'smooth',block:'center'});var first=card.querySelector('[data-f="'+(o.title?'what':'title')+'"]');if(first)first.focus({preventScroll:!0})}}
renderShell()})()